<?php
declare(strict_types=1);
require __DIR__.'/_bootstrap.php';
$user=require_admin();$db=admin_db();
$pages=[
 ['Inicio','/','inicio','es'],['Nosotros','/nosotros/','nosotros','es'],['Productos','/productos/','productos','es'],['Línea Convencional','/productos/linea-convencional/','productos-conventional','es'],['Línea Retail','/productos/linea-retail/','productos-retail','es'],['Participación','/participacion/','participacion','es'],['Presencia','/presencia/','presencia','es'],['Impacto','/impacto/','impacto','es'],['Contacto','/contacto/','contacto','es'],
 ['Home · English','/en/','inicio','en'],['About · English','/en/about-us/','nosotros','en'],['Products · English','/en/products/','productos','en'],['Conventional line · English','/en/products/conventional-line/','productos-conventional','en'],['Retail line · English','/en/products/retail-line/','productos-retail','en'],['Events · English','/en/events/','participacion','en'],['Presence · English','/en/presence/','presencia','en'],['Impact · English','/en/impact/','impacto','en'],['Contact · English','/en/contact/','contacto','en']
];
$products=$db->query("SELECT p.id,l.slug line_slug,MAX(CASE WHEN t.locale='es' THEN t.name END) name_es,MAX(CASE WHEN t.locale='es' THEN t.slug END) slug_es,MAX(CASE WHEN t.locale='en' THEN t.name END) name_en,MAX(CASE WHEN t.locale='en' THEN t.slug END) slug_en FROM products p JOIN product_lines l ON l.id=p.line_id JOIN product_translations t ON t.product_id=p.id WHERE p.is_active=1 AND p.deleted_at IS NULL GROUP BY p.id,l.slug ORDER BY name_es")->fetchAll();
foreach($products as $product){$pages[]=['Producto · '.$product['name_es'],'/productos/'.($product['line_slug']==='retail'?'linea-retail':'linea-convencional').'/'.$product['slug_es'].'/','product-'.$product['id'],'es'];$pages[]=['Product · '.$product['name_en'],'/en/products/'.($product['line_slug']==='retail'?'retail-line':'conventional-line').'/'.$product['slug_en'].'/','product-'.$product['id'],'en'];}
