:11px}.element-list{max-height:150px;display:grid;gap:5px;margin-top:11px;overflow:auto}.element-list button{width:100%;display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 10px;border:1px solid #e1e6e6;border-radius:7px;color:#44544d;background:#f8faf7;text-align:left;font-size:11px}.element-list button:hover,.element-list button.active{border-color:#91bd72;color:#052f26;background:#edf8e4}.inspector-content{min-height:0;overflow:auto;padding:20px}.inspector-empty{height:100%;display:grid;place-content:center;text-align:center;color:#71808a}.inspector-empty[hidden],.inspector-form[hidden],.product-inspector[hidden]{display:none!important}.inspector-empty span{width:52px;height:52px;display:grid;place-items:center;margin:0 auto 18px;border-radius:14px;color:#075e53;background:#e9f7dc}.inspector-form{display:grid;gap:14px}.inspector-form h2{margin:0;font-size:21px}.inspector-form label{display:grid;gap:6px;font-size:12px;font-weight:700}.inspector-form input,.inspector-form textarea,.inspector-form select{width:100%;padding:10px;border:1px solid #d2dce0;border-radius:7px;color:#263a34;background:#fff}.inspector-form textarea{min-height:125px;resize:vertical}.save-bar{position:sticky;bottom:-20px;display:grid;gap:7px;margin:8px -20px -20px;padding:13px 20px 20px;border-top:1px solid #e0e6e7;background:#fff}.save-bar button,.product-edit-link{min-height:44px;padding:11px;border:0;border-radius:8px;color:#052f26;background:#c6ee9b;font-weight:700;text-align:center}.save-state{min-height:18px;margin:0;color:#477555;font-size:11px}.product-inspector{display:grid;gap:14px}.product-inspector h2{margin:0}.admin-return{display:inline-flex;margin:17px 10px 0;color:#c6ee9b;font-size:12px}
