@media(max-width:520px){.editor-main{height:calc(100svh - 126px)}.editor-toolbar{grid-template-columns:1fr}.toolbar-field{min-width:0}.device-switch{grid-column:auto}.public-link{display:none}.editor-inspector{left:6px;right:6px;bottom:6px;width:auto;max-height:72svh;border-radius:14px}.inspector-content{padding:16px}.save-bar{margin-left:-16px;margin-right:-16px;padding-left:16px;padding-right:16px}.preview-frame.tablet,.preview-frame.mobile{width:390px;flex-basis:390px}}
.inspector-close,.inspector-reopen{display:none}@media(max-width:850px){.inspector-close{display:inline-grid;place-items:center;width:34px;height:34px;border:1px solid #d8e0df;border-radius:7px;color:#365149;background:#fff}.inspector-reopen{position:fixed;z-index:49;right:14px;bottom:14px;width:52px;height:52px;place-items:center;border:0;border-radius:50%;color:#052f26;background:#c6ee9b;box-shadow:0 10px 30px #052f2640}.editor-body.inspector-collapsed .editor-inspector{display:none}.editor-body.inspector-collapsed .inspector-reopen{display:grid}.element-list{max-height:150px}}</style></head><body class="admin-body editor-body"><aside class="admin-sidebar"><a class="admin-brand" href="/admin/"><img src="/images/logo.webp" alt=""><span><strong>ROYAL BEANS</strong><small>ADMINISTRACIÓN</small></span></a><nav><a href="/admin/">Resumen</a><a href="/admin/?view=products">Productos</a><a class="active" href="/admin/editor.php">Editor visual</a><a href="/admin/?view=media">Imágenes</a><a href="/admin/?view=inquiries">Consultas</a><a href="/admin/?view=settings">Configuración</a><?php if($user['role']==='admin'):?><a href="/admin/?view=users">Usuarios</a><?php endif;?></nav><a class="admin-return" href="/" target="_blank">Ver sitio público</a><div class="admin-user"><strong><?=e($user['name'])?></strong><small><?=e($user['role'])?></small><a href="/admin/?view=logout">Cerrar sesión</a></div></aside><main class="editor-main"><header class="editor-toolbar"><label class="toolbar-field">Página<select id="page-picker"><?php foreach($pages as [$label,$url,$key,$lang]):?><option value="<?=e($url)?>" data-page="<?=e($key)?>" data-lang="<?=$lang?>"><?=e($label)?></option><?php endforeach;?></select></label><label class="toolbar-field">Sección<select id="section-picker"><option value="">Todas las secciones</option></select></label><div class="device-switch" aria-label="Tamaño de vista"><button class="active" data-device="monitor">Monitor</button><button data-device="tablet">Tablet</button><button data-device="mobile">Celular</button></div><p class="editor-hint">Selecciona una sección y luego un elemento. La navegación de la vista está bloqueada.</p><a id="public-link" class="public-link" href="/" target="_blank">Vista pública ↗</a></header><section class="editor-workspace"><div class="preview-shell"><iframe id="preview" class="preview-frame" src="/?cms_preview=1" title="Vista editable"></iframe></div><aside class="editor-inspector"><section class="element-browser"><div class="element-browser-head"><h2>Elementos de la sección</h2><span id="element-count">0 elementos</span><button id="inspector-close" class="inspector-close" type="button" aria-label="Cerrar inspector"><svg viewBox="0 0 24 24" width="18" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></button></div><div id="element-list" class="element-list"><span>Selecciona una sección para ver sus campos.</span></div></section><div class="inspector-content"><div id="empty" class="inspector-empty"><div><span><svg viewBox="0 0 24 24" width="24" aria-hidden="true"><circle cx="12" cy="12" r="3" fill="none" stroke="currentColor" stroke-width="1.7"/><path d="M12 3v3M12 18v3M3 12h3M18 12h3M5.6 5.6l2.1 2.1M16.3 16.3l2.1 2.1M18.4 5.6l-2.1 2.1M7.7 16.3l-2.1 2.1" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg></span><h2>Selecciona un elemento</h2><p>El formulario sustituirá este mensaje.</p></div></div><form id="field-form" class="inspector-form" hidden enctype="multipart/form-data"><p class="admin-eyebrow">Elemento seleccionado</p><h2 id="field-name">Contenido</h2><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="page_key"><input type="hidden" name="key"><input type="hidden" name="editing_lang"><label>Tipo<select name="field_type"><option value="text">Texto corto</option><option value="textarea">Texto largo</option><option value="image">Imagen</option><option value="url">Enlace</option></select></label><label>Nombre en el panel<input name="label"></label><label>Español<textarea name="value_es"></textarea></label><label>English<textarea name="value_en"></textarea></label><label id="image-upload" hidden>Nueva imagen<input type="file" name="image" accept="image/jpeg,image/png,image/webp,image/avif"></label><div class="save-bar"><button>Guardar y actualizar vista</button><p class="save-state" role="status"></p></div></form><div id="product-inspector" class="product-inspector" hidden><p class="admin-eyebrow">Ficha de producto</p><h2>Información estructurada</h2><p>Especificaciones, galería, empaques, calendario y productos relacionados se administran desde su ficha.</p><a id="product-edit-link" class="product-edit-link">Editar ficha completa</a></div></div></aside><button id="inspector-reopen" class="inspector-reopen" type="button" aria-label="Abrir inspector"><svg viewBox="0 0 24 24" width="22" aria-hidden="true"><path d="m4 16-.7 4 4-.7L18 8.6 14.4 5 4 16Z" fill="none" stroke="currentColor" stroke-width="1.7"/><path d="m12.8 6.6 3.6 3.6" fill="none" stroke="currentColor" stroke-width="1.7"/></svg></button></section></main><script>
const picker=document.querySelector('#page-picker'),sectionPicker=document.querySelector('#section-picker'),frame=document.querySelector('#preview'),form=document.querySelector('#field-form'),empty=document.querySelector('#empty'),productBox=document.querySelector('#product-inspector'),publicLink=document.querySelector('#public-link'),elementList=document.querySelector('#element-list'),elementCount=document.querySelector('#element-count'),inspectorClose=document.querySelector('#inspector-close'),inspectorReopen=document.querySelector('#inspector-reopen');let selected=null,editable=[];
function current(){const option=picker.selectedOptions[0];return{url:option.value,page:option.dataset.page,lang:option.dataset.lang}}
function resetInspector(){selected=null;form.hidden=true;productBox.hidden=true;empty.hidden=false;document.querySelectorAll('.element-list button').forEach(button=>button.classList.remove('active'))}
function loadPage(){const item=current();frame.src=item.url+(item.url.includes('?')?'&':'?')+'cms_preview=1';publicLink.href=item.url;sectionPicker.innerHTML='<option value="">Todas las secciones</option>';elementList.innerHTML='<span>Cargando elementos…</span>';elementCount.textContent='0 elementos';resetInspector()}
picker.addEventListener('change',loadPage);document.querySelectorAll('[data-device]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-device]').forEach(item=>item.classList.remove('active'));button.classList.add('active');frame.className='preview-frame '+(button.dataset.device==='monitor'?'':button.dataset.device)}));
function labelFor(element){if(element instanceof HTMLImageElement)return element.alt||'Imagen';const text=(element.textContent||'').trim().replace(/\s+/g,' ');return text.slice(0,58)||element.dataset.cms}
function refreshElements(){const section=sectionPicker.value;const filtered=section?editable.filter(element=>element.dataset.cms?.split('.')[0]===section):editable;elementList.innerHTML='';filtered.forEach(element=>{const button=document.createElement('button');button.type='button';button.innerHTML='<span></span><small></small>';button.querySelector('span').textContent=labelFor(element);button.querySelector('small').textContent=element.tagName.toLowerCase();button.addEventListener('click',()=>{element.scrollIntoView({behavior:'smooth',block:'center'});showField(element.dataset.cms,element,button)});elementList.append(button)});elementCount.textContent=filtered.length+' elementos';if(!filtered.length)elementList.innerHTML='<span>No hay elementos editables en esta sección.</span>'}
sectionPicker.addEventListener('change',()=>{resetInspector();refreshElements();const doc=frame.contentDocument,section=doc?.querySelector('[data-cms-section="'+CSS.escape(sectionPicker.value)+'"]');section?.scrollIntoView({behavior:'smooth',block:'start'})});
frame.addEventListener('load',()=>{const doc=frame.contentDocument;if(!doc)return;const style=doc.createElement('style');style.textContent='[data-cms],[data-product-id]{cursor:pointer!important;outline:1px dashed transparent!important;outline-offset:4px;transition:outline-color .2s,box-shadow .2s}[data-cms]:hover,[data-product-id]:hover{outline-color:#79b855!important;box-shadow:0 0 0 5px #c6ee9b33!important}';doc.head.append(style);const collect=()=>{editable=Array.from(doc.querySelectorAll('[data-cms]'));const sections=[...new Set(editable.map(element=>element.dataset.cms.split('.')[0]))];const selectedSection=sectionPicker.value;sectionPicker.innerHTML='<option value="">Todas las secciones</option>'+sections.map(section=>'<option value="'+section+'">'+section.replace(/-/g,' ')+'</option>').join('');if(sections.includes(selectedSection))sectionPicker.value=selectedSection;refreshElements()};collect();setTimeout(collect,500);doc.addEventListener('submit',event=>event.preventDefault(),true);doc.addEventListener('click',event=>{const target=event.target.closest('[data-cms],[data-product-id]');event.preventDefault();event.stopPropagation();event.stopImmediatePropagation();if(!target)return;if(target.dataset.productId){showProduct(target.dataset.productId);return}showField(target.dataset.cms,target)},true)});
async function showField(key,element,listButton){document.body.classList.remove('inspector-collapsed');selected=element;empty.hidden=true;productBox.hidden=true;form.hidden=false;document.querySelectorAll('.element-list button').forEach(button=>button.classList.toggle('active',button===listButton));const item=current(),response=await fetch('/admin/editor-api.php?page='+encodeURIComponent(item.page)+'&key='+encodeURIComponent(key)),payload=await response.json(),field=payload.field;form.page_key.value=item.page;form.key.value=key;form.editing_lang.value=item.lang;const detected=element instanceof HTMLImageElement?'image':((element.textContent||'').trim().length>90?'textarea':'text');form.field_type.value=field.id?field.field_type:detected;form.label.value=field.id?field.label:labelFor(element);form.value_es.value=field.value_es||(item.lang==='es'?(element instanceof HTMLImageElement?element.src:element.textContent.trim()):'');form.value_en.value=field.value_en||(item.lang==='en'?(element instanceof HTMLImageElement?element.src:element.textContent.trim()):'');document.querySelector('#field-name').textContent=form.label.value;document.querySelector('#image-upload').hidden=form.field_type.value!=='image'}
function showProduct(id){document.body.classList.remove('inspector-collapsed');empty.hidden=true;form.hidden=true;productBox.hidden=false;document.querySelector('#product-edit-link').href='/admin/product-details.php?id='+id}
inspectorClose.addEventListener('click',()=>document.body.classList.add('inspector-collapsed'));inspectorReopen.addEventListener('click',()=>document.body.classList.remove('inspector-collapsed'));form.field_type.addEventListener('change',()=>document.querySelector('#image-upload').hidden=form.field_type.value!=='image');form.addEventListener('submit',async event=>{event.preventDefault();const state=form.querySelector('.save-state');state.textContent='Guardando…';const response=await fetch('/admin/editor-api.php',{method:'POST',body:new FormData(form)}),payload=await response.json();if(!response.ok){state.textContent=payload.error||'No se pudo guardar';return}const value=payload[current().lang==='en'?'value_en':'value_es'];if(selected&&value){if(payload.type==='image')selected.src=value;else if(payload.type==='url')selected.href=value;else selected.textContent=value}state.textContent='Cambios guardados';refreshElements();setTimeout(()=>state.textContent='',1800)});
</script></body></html>
